331	/// The workspace package with this exact release identity.
332	pub(crate) fn workspace_package<'w, R: callisto_model::CommandRunner, D: DependencyResolver>(
333	    workspace: &'w Workspace<'_, R, D>,
334	    id: &ReleasePackageId,
335	) -> Option<&'w Package> {
336	    // By release identity, not name: a dual-manifest package's npm name can differ from its id.
337	    workspace
338	        .graph
339	        .packages()
340	        .find(|package| release_package_ids(&workspace.identity, package).is_ok_and(|ids| ids.contains(id)))
341	}
342	
343	/// The fixed and linked groups a release package belongs to, per config.
344	fn release_groups_of<R: callisto_model::CommandRunner, D: DependencyResolver>(
345	    workspace: &Workspace<'_, R, D>,
346	    id: &ReleasePackageId,
347	) -> Vec<(&'static str, callisto_model::GroupName)> {
348	    let Some(package) = workspace_package(workspace, id) else {
349	        return Vec::new();
350	    };
351	    let groups = &workspace.config.groups;
352	    let fixed = groups.fixed_of.iter().map(|(member, group)| ("fixed", member, group));
353	    let linked = groups.linked_of.iter().map(|(member, group)| ("linked", member, group));
354	    // `member` keys are already canonical (`GroupTable::resolve` resolved
355	    // them through `IdentityIndex::resolve`), so exact equality is correct
356	    // here -- `PackageId::matches` would treat a Bare member key as an
357	    // ecosystem wildcard and could match a same-named package elsewhere.
358	    fixed
359	        .chain(linked)
360	        .filter(|(_, member, _)| **member == package.id)
361	        .map(|(kind, _, group)| (kind, group.clone()))
362	        .collect()
363	}
364	
365	/// Verifies the release roster a merged release commit claims, against a
366	/// release-decision file committed alongside it at `decision_path`.
367	///
368	/// This is intentionally *not* a second computation of changeset, fixed-group,
369	/// linked-group, cascade, or pre-release-policy inclusion. `plan_version`
370	/// (via [`derive_release_decision`]) already computed that once, correctly,
371	/// when the release PR was generated -- and `callisto version --emit-decision`
372	/// commits its exact output alongside the manifest and changelog edits.
373	/// Re-deriving that policy a second time here, from raw git diffs, is exactly
374	/// the kind of duplicated logic that drifts: an earlier version of this
375	/// function did just that, understood only a direct changeset match, and
376	/// rejected every real release in this repository once a fixed-group cascade
377	/// (a case its reimplementation never learned) touched an unnamed sibling.
378	///
379	/// Instead, this function reads the committed decision back and confirms the
380	/// commit's actual diff matches it exactly -- no more, no less.
381	/// [`ReleaseDecisionV1`]'s own deserializer already rejects a decision whose
382	/// entries don't match its content digest, so a hand-edited or corrupted
383	/// decision file fails before this function's own diff cross-check runs.
384	///
385	/// The caller must check out the exact merge commit in detached HEAD state
386	/// before creating an intent. GitHub-specific PR/approval provenance belongs
387	/// in the workflow boundary; this graph function verifies the local,
388	/// provider-neutral commit delta only.
389	pub fn derive_release_commit_decision<R: CommandRunner, D: DependencyResolver>(
390	    workspace: &Workspace<'_, R, D>,
391	    release_commit: &CommitSha,
392	    decision_path: &std::path::Path,
393	) -> Result<ReleaseDecisionV1, GraphError> {
394	    let (parent, changed) = commit_delta(workspace, release_commit)?;
395	    let decision_path_str = normalized_git_path(decision_path)?;
396	    require_version_commit_shape(workspace, release_commit, &changed, &decision_path_str)?;
397	    let decision = read_committed_decision(workspace, release_commit, decision_path, &decision_path_str)?;
398	    require_manifests_match_decision(workspace, release_commit, &parent, &changed, &decision)?;
399	    Ok(decision)
400	}
401	
402	/// The commit's parent and what the commit changed against it, as `(status, path)` pairs. Fails unless `HEAD` is the
403	/// release commit.
404	fn commit_delta<R: CommandRunner, D: DependencyResolver>(
405	    workspace: &Workspace<'_, R, D>,
406	    release_commit: &CommitSha,
407	) -> Result<(String, Vec<(String, String)>), GraphError> {
408	    let head_args = ["rev-parse", "HEAD"];
409	    let head = git_stdout(workspace.runner, &workspace.root, &head_args)?;
410	    let head =
411	        CommitSha::parse(&head).map_err(|source| command_malformed_output("git", &head_args, source.to_string()))?;
412	    if &head != release_commit {
413	        return Err(GraphError::ReleaseCommitVerificationFailed {
414	            commit: release_commit.clone(),
415	            reason: CommitVerificationFailure::HeadMismatch,
416	        });
417	    }
418	
419	    let parent_ref = format!("{}^", release_commit.as_str());
420	    let parent_args = ["rev-parse", parent_ref.as_str()];
421	    let parent = git_stdout(workspace.runner, &workspace.root, &parent_args)?;
422	    CommitSha::parse(&parent).map_err(|source| command_malformed_output("git", &parent_args, source.to_string()))?;
423	
424	    let diff_tree_args = [
425	        "diff-tree",
426	        "--no-commit-id",
427	        "--name-status",
428	        "-r",
429	        "--no-renames",
430	        parent.as_str(),
431	        release_commit.as_str(),
432	    ];
433	    let changed = git_stdout(workspace.runner, &workspace.root, &diff_tree_args)?;
434	    let changed = parse_name_status(&changed, &diff_tree_args)?;
435	    Ok((parent, changed))
436	}
