438	/// The commit has the shape of a version commit: it wrote the decision, consumed a changeset, and touched only the
439	/// paths a version commit may touch.
440	fn require_version_commit_shape<R: CommandRunner, D: DependencyResolver>(
441	    workspace: &Workspace<'_, R, D>,
442	    release_commit: &CommitSha,
443	    changed: &[(String, String)],
444	    decision_path: &str,
445	) -> Result<(), GraphError> {
446	    let changeset_dir = normalized_git_path(&workspace.config.changesets_dir)?;
447	
448	    // The decision must be freshly authored as part of *this* commit, not a
449	    // stale leftover an earlier release already committed and this one never
450	    // touched -- otherwise a commit that changes nothing real could still
451	    // carry forward a prior, unrelated decision's authority.
452	    let decision_freshly_written = changed
453	        .iter()
454	        .any(|(status, path)| path == decision_path && matches!(status.as_str(), "A" | "M"));
455	    if !decision_freshly_written {
456	        return Err(GraphError::ReleaseCommitVerificationFailed {
457	            commit: release_commit.clone(),
458	            reason: CommitVerificationFailure::DecisionNotWrittenByCommit,
459	        });
460	    }
461	
462	    // A cheap, independent sanity check that this commit is a real version
463	    // application and not just a hand-crafted decision file: some real
464	    // changeset was actually consumed. The decision's own entries, not this
465	    // changeset's content, remain the sole authority verified below.
466	    let consumed_a_changeset = changed
467	        .iter()
468	        .any(|(status, path)| status == "D" && is_changeset_path(path, &changeset_dir));
469	    if !consumed_a_changeset {
470	        return Err(GraphError::ReleaseCommitVerificationFailed {
471	            commit: release_commit.clone(),
472	            reason: CommitVerificationFailure::NoChangesetConsumed,
473	        });
474	    }
475	
476	    // A version commit changes versions and what records them, nothing else. Any other path (build scripts, source,
477	    // a package manager's `.npmrc` or `.cargo/config.toml`, `callisto.toml`, an action) could change what is published
478	    // or where, under the cover of a bot-authored diff.
479	    let changelogs = workspace
480	        .graph
481	        .packages()
482	        .filter_map(|package| package.changelog.as_deref())
483	        .map(normalized_git_path)
484	        .collect::<Result<std::collections::BTreeSet<_>, _>>()?;
485	    for (_, path) in changed {
486	        if !is_version_commit_path(path, decision_path, &changeset_dir, &changelogs) {
487	            return Err(GraphError::ReleaseCommitVerificationFailed {
488	                commit: release_commit.clone(),
489	                reason: CommitVerificationFailure::UnexpectedPath { path: path.clone() },
490	            });
491	        }
492	    }
493	    Ok(())
494	}
