496	/// The decision file as the release commit holds it. Its own deserializer rejects entries that do not match its digest.
497	fn read_committed_decision<R: CommandRunner, D: DependencyResolver>(
498	    workspace: &Workspace<'_, R, D>,
499	    release_commit: &CommitSha,
500	    decision_path: &std::path::Path,
501	    decision_path_str: &str,
502	) -> Result<ReleaseDecisionV1, GraphError> {
503	    let decision_source = git_file(
504	        workspace.runner,
505	        &workspace.root,
506	        release_commit.as_str(),
507	        decision_path_str,
508	    )?;
509	    serde_json::from_str(&decision_source).map_err(|error| GraphError::ReleaseDecisionDecode {
510	        path: decision_path.to_path_buf(),
511	        message: error.to_string(),
512	    })
513	}
514	
515	/// Every package the decision claims has its changelog and manifest in the diff with exactly the claimed version, and
516	/// no package the decision does not claim changed version.
517	fn require_manifests_match_decision<R: CommandRunner, D: DependencyResolver>(
518	    workspace: &Workspace<'_, R, D>,
519	    release_commit: &CommitSha,
520	    parent: &str,
521	    changed: &[(String, String)],
522	    decision: &ReleaseDecisionV1,
523	) -> Result<(), GraphError> {
524	    let claimed = decision
525	        .entries
526	        .iter()
527	        .map(|entry| (entry.package.clone(), entry.target_version.clone()))
528	        .collect::<std::collections::BTreeMap<_, _>>();
529	
530	    let changed_paths = changed
531	        .iter()
532	        .filter_map(|(status, path)| matches!(status.as_str(), "A" | "M").then_some(path.as_str()))
533	        .collect::<std::collections::BTreeSet<_>>();
534	
535	    // Every canonical manifest path this workspace currently declares, in
536	    // the exact order `workspace.graph.packages()` and
537	    // `Package::canonical_manifests()` yield -- both are backed by ordered
538	    // (`BTreeMap`/`Vec`) storage with no interior mutation between calls, so
539	    // the second traversal below visits the same (package, manifest) pairs
540	    // in the same order. That lets it zip the batched `before`/`after`
541	    // results back on by position instead of re-keying by path, which would
542	    // misbehave if two packages ever declared an identical manifest path.
543	    let manifest_queries: Vec<(String, Ecosystem)> = workspace
544	        .graph
545	        .packages()
546	        .flat_map(Package::canonical_manifests)
547	        .map(|manifest| Ok((normalized_git_path(&manifest.path)?, manifest.ecosystem())))
548	        .collect::<Result<_, GraphError>>()?;
549	    // Each Cargo manifest may inherit its version from a workspace manifest above it, so those are fetched too.
550	    let mut query_path_list: Vec<String> = manifest_queries.iter().map(|(path, _)| path.clone()).collect();
551	    for (path, _) in manifest_queries
552	        .iter()
553	        .filter(|(_, ecosystem)| *ecosystem == Ecosystem::Cargo)
554	    {
555	        for candidate in callisto_manifests::workspace_manifest_candidates(&workspace.root, std::path::Path::new(path))?
556	        {
557	            let candidate = normalized_git_path(&candidate)?;
558	            if !query_path_list.contains(&candidate) {
559	                query_path_list.push(candidate);
560	            }
561	        }
562	    }
563	    let query_paths: Vec<&str> = query_path_list.iter().map(String::as_str).collect();
564	
565	    // Exactly two `git cat-file --batch` subprocess invocations total (one
