/// The fixed and linked groups a release package belongs to, per config.
fn release_groups_of<R: callisto_model::CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    id: &ReleasePackageId,
) -> Vec<(&'static str, callisto_model::GroupName)> {
    let Some(package) = workspace_package(workspace, id) else {
        return Vec::new();
    };
    let groups = &workspace.config.groups;
    let fixed = groups.fixed_of.iter().map(|(member, group)| ("fixed", member, group));
    let linked = groups.linked_of.iter().map(|(member, group)| ("linked", member, group));
    // `member` keys are already canonical (`GroupTable::resolve` resolved
    // them through `IdentityIndex::resolve`), so exact equality is correct
    // here -- `PackageId::matches` would treat a Bare member key as an
    // ecosystem wildcard and could match a same-named package elsewhere.
    fixed
        .chain(linked)
        .filter(|(_, member, _)| **member == package.id)
        .map(|(kind, _, group)| (kind, group.clone()))
        .collect()
}

/// Verifies the release roster a merged release commit claims, against a
/// release-decision file committed alongside it at `decision_path`.
///
/// This is intentionally *not* a second computation of changeset, fixed-group,
/// linked-group, cascade, or pre-release-policy inclusion. `plan_version`
/// (via [`derive_release_decision`]) already computed that once, correctly,
/// when the release PR was generated -- and `callisto version --emit-decision`
/// commits its exact output alongside the manifest and changelog edits.
/// Re-deriving that policy a second time here, from raw git diffs, is exactly
/// the kind of duplicated logic that drifts: an earlier version of this
/// function did just that, understood only a direct changeset match, and
/// rejected every real release in this repository once a fixed-group cascade
/// (a case its reimplementation never learned) touched an unnamed sibling.
///
/// Instead, this function reads the committed decision back and confirms the
/// commit's actual diff matches it exactly -- no more, no less.
/// [`ReleaseDecisionV1`]'s own deserializer already rejects a decision whose
/// entries don't match its content digest, so a hand-edited or corrupted
/// decision file fails before this function's own diff cross-check runs.
///
/// The caller must check out the exact merge commit in detached HEAD state
/// before creating an intent. GitHub-specific PR/approval provenance belongs
/// in the workflow boundary; this graph function verifies the local,
/// provider-neutral commit delta only.
pub fn derive_release_commit_decision<R: CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    release_commit: &CommitSha,
    decision_path: &std::path::Path,
) -> Result<ReleaseDecisionV1, GraphError> {
    let (parent, changed) = commit_delta(workspace, release_commit)?;
    let decision_path_str = normalized_git_path(decision_path)?;
    require_version_commit_shape(workspace, release_commit, &changed, &decision_path_str)?;
    let decision = read_committed_decision(workspace, release_commit, decision_path, &decision_path_str)?;
    require_manifests_match_decision(workspace, release_commit, &parent, &changed, &decision)?;
    Ok(decision)
}

/// The commit's parent and what the commit changed against it, as `(status, path)` pairs. Fails unless `HEAD` is the
/// release commit.
fn commit_delta<R: CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    release_commit: &CommitSha,
) -> Result<(String, Vec<(String, String)>), GraphError> {
    let head_args = ["rev-parse", "HEAD"];
    let head = git_stdout(workspace.runner, &workspace.root, &head_args)?;
    let head =
        CommitSha::parse(&head).map_err(|source| command_malformed_output("git", &head_args, source.to_string()))?;
    if &head != release_commit {
        return Err(GraphError::ReleaseCommitVerificationFailed {
            commit: release_commit.clone(),
            reason: CommitVerificationFailure::HeadMismatch,
        });
    }

    let parent_ref = format!("{}^", release_commit.as_str());
    let parent_args = ["rev-parse", parent_ref.as_str()];
    let parent = git_stdout(workspace.runner, &workspace.root, &parent_args)?;
    CommitSha::parse(&parent).map_err(|source| command_malformed_output("git", &parent_args, source.to_string()))?;

    let diff_tree_args = [
        "diff-tree",
        "--no-commit-id",
        "--name-status",
        "-r",
        "--no-renames",
        parent.as_str(),
        release_commit.as_str(),
    ];
    let changed = git_stdout(workspace.runner, &workspace.root, &diff_tree_args)?;
    let changed = parse_name_status(&changed, &diff_tree_args)?;
    Ok((parent, changed))
}

/// The commit has the shape of a version commit: it wrote the decision, consumed a changeset, and touched only the
/// paths a version commit may touch.
fn require_version_commit_shape<R: CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    release_commit: &CommitSha,
    changed: &[(String, String)],
    decision_path: &str,
) -> Result<(), GraphError> {
    let changeset_dir = normalized_git_path(&workspace.config.changesets_dir)?;

    // The decision must be freshly authored as part of *this* commit, not a
    // stale leftover an earlier release already committed and this one never
    // touched -- otherwise a commit that changes nothing real could still
    // carry forward a prior, unrelated decision's authority.
    let decision_freshly_written = changed
        .iter()
        .any(|(status, path)| path == decision_path && matches!(status.as_str(), "A" | "M"));
    if !decision_freshly_written {
        return Err(GraphError::ReleaseCommitVerificationFailed {
            commit: release_commit.clone(),
            reason: CommitVerificationFailure::DecisionNotWrittenByCommit,
        });
    }

    // A cheap, independent sanity check that this commit is a real version
    // application and not just a hand-crafted decision file: some real
    // changeset was actually consumed. The decision's own entries, not this
    // changeset's content, remain the sole authority verified below.
    let consumed_a_changeset = changed
        .iter()
        .any(|(status, path)| status == "D" && is_changeset_path(path, &changeset_dir));
    if !consumed_a_changeset {
        return Err(GraphError::ReleaseCommitVerificationFailed {
            commit: release_commit.clone(),
            reason: CommitVerificationFailure::NoChangesetConsumed,
        });
    }

    // A version commit changes versions and what records them, nothing else. Any other path (build scripts, source,
    // a package manager's `.npmrc` or `.cargo/config.toml`, `callisto.toml`, an action) could change what is published
    // or where, under the cover of a bot-authored diff.
    let changelogs = workspace
        .graph
        .packages()
        .filter_map(|package| package.changelog.as_deref())
        .map(normalized_git_path)
        .collect::<Result<std::collections::BTreeSet<_>, _>>()?;
    for (_, path) in changed {
        if !is_version_commit_path(path, decision_path, &changeset_dir, &changelogs) {
            return Err(GraphError::ReleaseCommitVerificationFailed {
                commit: release_commit.clone(),
                reason: CommitVerificationFailure::UnexpectedPath { path: path.clone() },
            });
        }
    }
    Ok(())
}

/// The decision file as the release commit holds it. Its own deserializer rejects entries that do not match its digest.
fn read_committed_decision<R: CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    release_commit: &CommitSha,
    decision_path: &std::path::Path,
    decision_path_str: &str,
) -> Result<ReleaseDecisionV1, GraphError> {
    let decision_source = git_file(
        workspace.runner,
        &workspace.root,
        release_commit.as_str(),
        decision_path_str,
    )?;
    serde_json::from_str(&decision_source).map_err(|error| GraphError::ReleaseDecisionDecode {
        path: decision_path.to_path_buf(),
        message: error.to_string(),
    })
}

/// Every package the decision claims has its changelog and manifest in the diff with exactly the claimed version, and
/// no package the decision does not claim changed version.
fn require_manifests_match_decision<R: CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    release_commit: &CommitSha,
    parent: &str,
    changed: &[(String, String)],
    decision: &ReleaseDecisionV1,
) -> Result<(), GraphError> {
    let claimed = decision
        .entries
        .iter()
        .map(|entry| (entry.package.clone(), entry.target_version.clone()))
        .collect::<std::collections::BTreeMap<_, _>>();

    let changed_paths = changed
        .iter()
        .filter_map(|(status, path)| matches!(status.as_str(), "A" | "M").then_some(path.as_str()))
        .collect::<std::collections::BTreeSet<_>>();

    // Every canonical manifest path this workspace currently declares, in
    // the exact order `workspace.graph.packages()` and
    // `Package::canonical_manifests()` yield -- both are backed by ordered
    // (`BTreeMap`/`Vec`) storage with no interior mutation between calls, so
    // the second traversal below visits the same (package, manifest) pairs
    // in the same order. That lets it zip the batched `before`/`after`
    // results back on by position instead of re-keying by path, which would
    // misbehave if two packages ever declared an identical manifest path.
    let manifest_queries: Vec<(String, Ecosystem)> = workspace
        .graph
        .packages()
        .flat_map(Package::canonical_manifests)
        .map(|manifest| Ok((normalized_git_path(&manifest.path)?, manifest.ecosystem())))
        .collect::<Result<_, GraphError>>()?;
    // Each Cargo manifest may inherit its version from a workspace manifest above it, so those are fetched too.
    let mut query_path_list: Vec<String> = manifest_queries.iter().map(|(path, _)| path.clone()).collect();
    for (path, _) in manifest_queries
        .iter()
        .filter(|(_, ecosystem)| *ecosystem == Ecosystem::Cargo)
    {
        for candidate in callisto_manifests::workspace_manifest_candidates(&workspace.root, std::path::Path::new(path))?
        {
            let candidate = normalized_git_path(&candidate)?;
            if !query_path_list.contains(&candidate) {
                query_path_list.push(candidate);
            }
        }
    }
    let query_paths: Vec<&str> = query_path_list.iter().map(String::as_str).collect();

    // Exactly two `git cat-file --batch` subprocess invocations total (one
    // per commit), regardless of how many canonical manifests the
    // workspace has -- replaces what was previously 2*N separate `git
    // show` spawns (one `manifest_version_at` call per manifest per
    // commit).
    let before_blobs = batch_manifest_blobs_at(workspace.runner, &workspace.root, parent, &query_paths)?;
    let after_blobs =
        batch_manifest_blobs_at(workspace.runner, &workspace.root, release_commit.as_str(), &query_paths)?;
    let before = CommitBlobs::new(workspace.runner, &workspace.root, parent, &query_paths, before_blobs);
    let after = CommitBlobs::new(
        workspace.runner,
        &workspace.root,
        release_commit.as_str(),
        &query_paths,
        after_blobs,
    );
    let before_versions = resolve_batch_versions(&before, &manifest_queries)?;
    let after_versions = resolve_batch_versions(&after, &manifest_queries)?;

    let mut observed = std::collections::BTreeSet::new();
    let mut manifest_index = 0usize;
    for package in workspace.graph.packages() {
        let package_ids = release_package_ids(&workspace.identity, package)?;
        let package_is_claimed = package_ids.iter().any(|id| claimed.contains_key(id));
        if package_is_claimed {
            let changelog = package.changelog.as_ref().ok_or(GraphError::ReleasePreconditionUnmet {
                requirement: ReleasePreconditionRequirement::ChangelogConfigured,
            })?;
            let changelog = normalized_git_path(changelog)?;
            if !changed_paths.contains(changelog.as_str()) {
                return Err(GraphError::ReleaseCommitVerificationFailed {
                    commit: release_commit.clone(),
                    reason: CommitVerificationFailure::ChangelogNotTouched,
                });
            }
        }
        for id in package_ids {
            let before = &before_versions[manifest_index];
            let after = &after_versions[manifest_index];
            manifest_index += 1;
            let changed_version = before.version != after.version;
            match claimed.get(&id) {
                Some(target_version) => {
                    if !changed_paths.contains(after.authority.to_string_lossy().as_ref()) {
                        return Err(GraphError::ReleaseCommitVerificationFailed {
                            commit: release_commit.clone(),
                            reason: CommitVerificationFailure::ManifestNotInDiff,
                        });
                    }
                    if !changed_version || &after.version != target_version {
                        return Err(GraphError::ReleaseCommitVerificationFailed {
                            commit: release_commit.clone(),
                            reason: CommitVerificationFailure::ManifestVersionMismatch,
                        });
                    }
                    observed.insert(id);
                }
                None => {
                    if changed_version {
                        // A changed version the committed decision never
                        // claimed is not this commit's authority -- fail
                        // closed rather than trust a partial match.
                        return Err(GraphError::ReleaseCommitVerificationFailed {
                            commit: release_commit.clone(),
                            reason: CommitVerificationFailure::UnclaimedVersionChange,
                        });
                    }
                }
            }
        }
    }
    if observed.len() != claimed.len() {
        return Err(GraphError::ReleaseCommitVerificationFailed {
            commit: release_commit.clone(),
            reason: CommitVerificationFailure::ClaimedPackageNotObserved,
        });
    }
    Ok(())
}

