const VERSION_MANIFESTS: &[&str] = &["Cargo.toml", "package.json", "pyproject.toml"];

/// The lockfiles Callisto refreshes after it writes versions.
const VERSION_LOCKFILES: &[&str] = &[
    "Cargo.lock",
    "package-lock.json",
    "npm-shrinkwrap.json",
    "pnpm-lock.yaml",
    "yarn.lock",
    "bun.lock",
    "bun.lockb",
